  1504  size_t
  1505  UA_calcSizeJson(const void *src, const UA_DataType *type,
  1506                  UA_String *namespaces, size_t namespaceSize,
  1507                  UA_String *serverUris, size_t serverUriSize,
  1508                  UA_Boolean useReversible) {
  1509      if(!src || !type)
  1510          return UA_STATUSCODE_BADINTERNALERROR;
  1511
  1512      /* Set up the context */
  1513      CtxJson ctx;
  1514      memset(&ctx, 0, sizeof(ctx));
  1515      ctx.pos = 0;
  1516      ctx.end = (const UA_Byte*)(uintptr_t)SIZE_MAX;
  1517      ctx.depth = 0;
  1518      ctx.namespaces = namespaces;
  1519      ctx.namespacesSize = namespaceSize;
  1520      ctx.serverUris = serverUris;
  1521      ctx.serverUrisSize = serverUriSize;
  1522      ctx.useReversible = useReversible;
  1523      ctx.calcOnly = true;
  1524
  1525      /* Encode */
  1526      status ret = encodeJsonJumpTable[type->typeKind](src, type, &ctx);
  1527      if(ret != UA_STATUSCODE_GOOD)
  1528          return 0;
  1529      return (size_t)ctx.pos;
  1530  }
