  1596  static UA_Boolean
  1597  isJsonTokenNull(const CtxJson *ctx, jsmntok_t *token) {
  1598      if(token->type != JSMN_PRIMITIVE)
  1599          return false;
  1600      char* elem = (char*)(ctx->pos + token->start);
  1601      return (elem[0] == 'n' && elem[1] == 'u' && elem[2] == 'l' && elem[3] == 'l');
  1602  }
  1603
  1604  UA_Boolean
  1605  isJsonNull(const CtxJson *ctx, const ParseCtx *parseCtx) {
  1606      if(parseCtx->index >= parseCtx->tokenCount)
  1607          return false;
  1608
  1609      if(parseCtx->tokenArray[parseCtx->index].type != JSMN_PRIMITIVE) {
  1610          return false;
  1611      }
  1612      char* elem = (char*)(ctx->pos + parseCtx->tokenArray[parseCtx->index].start);
  1613      return (elem[0] == 'n' && elem[1] == 'u' && elem[2] == 'l' && elem[3] == 'l');
  1614  }
