   384  static UA_StatusCode
   385  ExtensionObject_copy(UA_ExtensionObject const *src, UA_ExtensionObject *dst,
   386                       const UA_DataType *_) {
   387      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   388      switch(src->encoding) {
   389      case UA_EXTENSIONOBJECT_ENCODED_NOBODY:
   390      case UA_EXTENSIONOBJECT_ENCODED_BYTESTRING:
   391      case UA_EXTENSIONOBJECT_ENCODED_XML:
   392          dst->encoding = src->encoding;
   393          retval = NodeId_copy(&src->content.encoded.typeId,
   394                               &dst->content.encoded.typeId, NULL);
   395          retval |= UA_ByteString_copy(&src->content.encoded.body,
   396                                       &dst->content.encoded.body);
   397          break;
   398      case UA_EXTENSIONOBJECT_DECODED:
   399      case UA_EXTENSIONOBJECT_DECODED_NODELETE:
   400          if(!src->content.decoded.type || !src->content.decoded.data)
   401              return UA_STATUSCODE_BADINTERNALERROR;
   402          dst->encoding = UA_EXTENSIONOBJECT_DECODED;
   403          dst->content.decoded.type = src->content.decoded.type;
   404          retval = UA_Array_copy(src->content.decoded.data, 1,
   405              &dst->content.decoded.data, src->content.decoded.type);
   406          break;
   407      default:
   408          break;
   409      }
   410      return retval;
   411  }
