   414  static void
   415  Variant_clear(UA_Variant *p, const UA_DataType *_) {
   416      if(p->storageType != UA_VARIANT_DATA)
   417          return;
   418      if(p->type && p->data > UA_EMPTY_ARRAY_SENTINEL) {
   419          if(p->arrayLength == 0)
   420              p->arrayLength = 1;
   421          UA_Array_delete(p->data, p->arrayLength, p->type);
   422          p->data = NULL;
   423      }
   424      if((void*)p->arrayDimensions > UA_EMPTY_ARRAY_SENTINEL)
   425          UA_free(p->arrayDimensions);
   426  }
