   428  static UA_StatusCode
   429  Variant_copy(UA_Variant const *src, UA_Variant *dst, const UA_DataType *_) {
   430      size_t length = src->arrayLength;
   431      if(UA_Variant_isScalar(src))
   432          length = 1;
   433      UA_StatusCode retval = UA_Array_copy(src->data, length,
   434                                           &dst->data, src->type);
   435      if(retval != UA_STATUSCODE_GOOD)
   436          return retval;
   437      dst->arrayLength = src->arrayLength;
   438      dst->type = src->type;
   439      if(src->arrayDimensions) {
   440          retval = UA_Array_copy(src->arrayDimensions, src->arrayDimensionsSize,
   441              (void**)&dst->arrayDimensions, &UA_TYPES[UA_TYPES_INT32]);
   442          if(retval != UA_STATUSCODE_GOOD)
   443              return retval;
   444          dst->arrayDimensionsSize = src->arrayDimensionsSize;
   445      }
   446      return UA_STATUSCODE_GOOD;
   447  }
